import{_ as e,c as r,o as t,ae as o}from"./chunks/framework.BbFa6TS3.js";const s="/Cherry-blog/assets/rag.BTpOEOtw.png",g=JSON.parse('{"title":"检索增强生成（RAG）","description":"","frontmatter":{},"headers":[],"relativePath":"fe/ai/rag.md","filePath":"fe/ai/rag.md"}'),i={name:"fe/ai/rag.md"};function n(l,a,_,c,d,p){return t(),r("div",null,a[0]||(a[0]=[o('<h1 id="检索增强生成-rag" tabindex="-1">检索增强生成（RAG） <a class="header-anchor" href="#检索增强生成-rag" aria-label="Permalink to &quot;检索增强生成（RAG）&quot;">​</a></h1><p>检索增强生成是一种结合信息检索和生成模型的技术架构，当用户提出查询时，系统首先从外部知识库（如数据库、文档集）中检索与查询相关的最新或特定领域信息片段；然后，将这些检索到的信息作为上下文，连同原始查询一起输入到 LLM 中，引导模型基于提供的外部知识生成更准确、更具事实依据的回答。RAG 系统首先根据查询从知识库中检索相关文档片段，然后将这些信息作为额外上下文提供给生成模型。这种方法有效解决了语言模型的知识陈旧性和信息幻觉问题。</p><p><img src="'+s+'" alt="rag"></p><h2 id="rag-技术" tabindex="-1">RAG 技术 <a class="header-anchor" href="#rag-技术" aria-label="Permalink to &quot;RAG 技术&quot;">​</a></h2><ul><li><a href="https://github.com/fareedkhan-dev/all-rag-techniques" target="_blank" rel="noreferrer">以更简单的方式实现所有 RAG 技术</a></li></ul>',5)]))}const f=e(i,[["render",n]]);export{g as __pageData,f as default};
